function drawGround(horizon, night) {
  const gradient = ctx.createLinearGradient(0, horizon, 0, H);
  gradient.addColorStop(0, night ? "#424945" : "#77776a");
  gradient.addColorStop(0.24, night ? "#292f2c" : "#464940");
  gradient.addColorStop(1, "#0a0e0d");
  ctx.fillStyle = gradient;
  ctx.fillRect(0, horizon, W, H - horizon);

  // Perspective-mapped mud, gravel and scattered wet patches on the street plane.
  const forwardX = Math.cos(game.angle),
    forwardY = Math.sin(game.angle),
    sideX = -forwardY,
    sideY = forwardX;
  for (let y = Math.ceil(horizon + 2); y < H; y += 3) {
    const depth = (H * 0.52) / (y - horizon),
      bandHeight = Math.min(7, 3 + depth * 0.012),
      fog = clamp((depth - 3) / 24, 0, night ? 0.74 : 0.58);
    for (let x = 0; x < W; x += 4) {
      const cameraX = (x / W - 0.5) * 1.12,
        lateral = cameraX * depth,
        wx = game.x + forwardX * depth + sideX * lateral,
        wy = game.y + forwardY * depth + sideY * lateral,
        grain = noise2(Math.floor(wx * 5), Math.floor(wy * 5)),
        patch = noise2(Math.floor(wx * 1.7), Math.floor(wy * 1.7)),
        wet = patch > 0.78 ? 0.13 : 0,
        tone = (grain - 0.5) * 0.16 - fog * 0.12 - wet;
      ctx.fillStyle = night
        ? `rgba(137,153,143,${clamp(0.035 + tone, 0.012, 0.12)})`
        : `rgba(194,184,157,${clamp(0.035 + tone, 0.01, 0.13)})`;
      ctx.fillRect(x, y, 4, bandHeight);
      if (wet > 0 && grain > 0.58) {
        ctx.fillStyle = `rgba(171,183,170,${(grain - 0.5) * 0.13})`;
        ctx.fillRect(x, y, 4, Math.max(1, bandHeight * 0.24));
      }
    }
  }
}

