for (const [name,viewport] of [['desktop',{width:1440,height:900}],['mobile',{width:390,height:844}]]) {
  const page=await browser.newPage({viewport});
  page.on('pageerror',e=>errors.push(`${name}: ${e.message}`));
  page.on('response',r=>{if(r.status()>=400 && new URL(r.url()).origin==='http://127.0.0.1:8765') errors.push(`${name}: HTTP ${r.status()} ${r.url()}`)});
  await page.goto('http://127.0.0.1:8765/',{waitUntil:'load'});
  await page.evaluate(()=>document.fonts.ready);
  await page.waitForTimeout(1400);
  await page.locator('#startButton').click();
  await page.waitForTimeout(300);
  const before=await page.evaluate(()=>({x:window.__THE_TOWN_TEST__.game.x,y:window.__THE_TOWN_TEST__.game.y,started:document.querySelector('#game').classList.contains('started')}));
  if(name==='desktop') {
    await page.keyboard.down('w'); await page.waitForTimeout(700); await page.keyboard.up('w');
    await page.keyboard.press('j'); await page.waitForTimeout(200);
    const journal=await page.locator('#panel').evaluate(el=>({open:el.classList.contains('open'),title:el.querySelector('#panelTitle')?.textContent}));
    await page.keyboard.press('Escape');
    await page.keyboard.press('m'); await page.waitForTimeout(150);
    const mapOpen=await page.locator('#mapPanel').evaluate(el=>el.classList.contains('open'));
    await page.keyboard.press('m');
    await page.waitForTimeout(800);
    await page.screenshot({path:'/tmp/opencode/broken-protocol-final.jpg',type:'jpeg',quality:90});
    console.log(JSON.stringify({name,before,after:await page.evaluate(()=>({x:window.__THE_TOWN_TEST__.game.x,y:window.__THE_TOWN_TEST__.game.y})),journal,mapOpen,screen:await page.locator('#game').evaluate(el=>el.getBoundingClientRect().toJSON())}));
  } else {
    await page.locator('[data-action="j"]').click();
    const journal=await page.locator('#panel').evaluate(el=>el.classList.contains('open'));
    await page.locator('#panelClose').click();
    await page.screenshot({path:'/tmp/opencode/final-mobile-review.jpg',type:'jpeg',quality:88});
    console.log(JSON.stringify({name,before,journal,controlsVisible:await page.locator('#mobile').isVisible(),viewport:await page.locator('#game').evaluate(el=>el.getBoundingClientRect().toJSON())}));
  }
  await page.close();
}
console.log('errors',JSON.stringify(errors));
await browser.close();
